    `source_identity_key`,
    `source_payload_hash`,
    `source_version_key`,
    `imported_at`,
    `capture_key`,
    `capture_at`,
    `is_source_present`,leadInFrame(toNullable(src_published_at)) over (partition by source_identity_key order by src_published_at rows between unbounded preceding and unbounded following) as next_at from {{ ref('stg_boond_projects') }} where capture_at<={{ utc_var('input_cutoff_at') }}), line_identity as (select src_tenant_id,src_id,min(src_published_at) as first_at,min(src_created_at) as created,countIf(src_created_at is null)=0 and uniqExact(src_created_at)=1 and min(src_created_at) is not null and min(src_created_at)<=min(src_published_at) and min(src_created_at)<=min(src_started_at) as reliable from h group by src_tenant_id,src_id), boundaries as (select src_tenant_id,src_id,src_published_at as boundary from h union distinct select h.src_tenant_id,h.src_id,p.src_published_at from h inner join projects p on h.src_tenant_id=p.src_tenant_id and h.src_project_id=p.src_id where p.src_published_at>h.src_published_at and (h.source_next_at is null or p.src_published_at<h.source_next_at) union distinct select h.src_tenant_id,h.src_id,co.valid_from_at from h inner join projects p on h.src_tenant_id=p.src_tenant_id and h.src_project_id=p.src_id inner join {{ ref('dim_company') }} co on co.model_run_id={{ ch_literal(var('model_run_id','parse_only')) }} and co.tenant_id=p.src_tenant_id and co.company_id=p.src_company_id where co.valid_from_at>h.src_published_at and (h.source_next_at is null or co.valid_from_at<h.source_next_at) and co.valid_from_at>=p.src_published_at and (p.next_at is null or co.valid_from_at<p.next_at)), slices as (select src_tenant_id,src_id,boundary,leadInFrame(toNullable(boundary)) over (partition by src_tenant_id,src_id order by boundary rows between unbounded preceding and unbounded following) as slice_end from boundaries), s as (select h.`src_tenant_id` AS `src_tenant_id`,
