    h.`capture_at` AS `capture_at`,
    h.`is_source_present` AS `is_source_present`,b.boundary,b.slice_end from slices b inner join h on b.src_tenant_id=h.src_tenant_id and b.src_id=h.src_id and b.boundary>=h.src_published_at and (h.source_next_at is null or b.boundary<h.source_next_at)),
business as (select
    CAST(greatest(co.source_published_at,s.src_published_at,p.src_published_at) AS Nullable(DateTime64(3,'UTC'))) AS `source_published_at`,
    CAST(arraySort(arrayDistinct(arrayFilter(x->x is not null,arrayConcat(ifNull(co.source_version_keys,[]),[s.source_version_key],[p.source_version_key])))) AS Array(String)) AS `source_version_keys`,
    CAST(lower(hex(SHA256(toJSONString(materialize(tuple('subscription_period_v1',tuple('subscription_key','String',if(isNull(subscription_key),'1','0'),ifNull(toString(subscription_key),'')),tuple('valid_from_at','DateTime64(3,\'UTC\')',if(isNull(s.boundary),'1','0'),ifNull(toString(toUnixTimestamp64Milli(s.boundary)),'')))))))) AS String) AS `subscription_period_key`,
    CAST(s.src_tenant_id AS String) AS `tenant_id`,
    CAST(s.src_id AS Int64) AS `line_id`,
    CAST(s.src_created_at AS Nullable(DateTime64(3,'UTC'))) AS `line_created_at`,
    CAST(li.reliable AS Bool) AS `is_creation_date_reliable`,
    CAST(lower(hex(SHA256(toJSONString(materialize(tuple('subscription_v1',tuple('tenant_id','String',if(isNull(s.src_tenant_id),'1','0'),ifNull(toString(s.src_tenant_id),'')),tuple('line_id','Int64',if(isNull(s.src_id),'1','0'),ifNull(toString(s.src_id),'')))))))) AS String) AS `subscription_key`,
    CAST(s.src_project_id AS Nullable(Int64)) AS `project_id`,
    CAST(if(p.src_id is not null,lower(hex(SHA256(toJSONString(materialize(tuple('project_v1',tuple('tenant_id','String',if(isNull(s.src_tenant_id),'1','0'),ifNull(toString(s.src_tenant_id),'')),tuple('project_id','Int64',if(isNull(p.src_id),'1','0'),ifNull(toString(p.src_id),'')))))))),NULL) AS Nullable(String)) AS `project_key`,
    CAST(p.src_company_id AS Nullable(Int64)) AS `company_id`,
    CAST(co.company_key AS Nullable(String)) AS `company_key`,
    CAST(co.company_version_key AS Nullable(String)) AS `company_version_key`,
    CAST(p.src_opportunity_id AS Nullable(Int64)) AS `opportunity_id`,
    CAST(s.boundary AS DateTime64(3,'UTC')) AS `valid_from_at`,
    CAST(s.slice_end AS Nullable(DateTime64(3,'UTC'))) AS `valid_to_at`,
    CAST(s.src_is_deleted AS Bool) AS `is_source_deleted`,
    CAST(p.src_is_deleted AS Nullable(Bool)) AS `is_project_deleted`,
    CAST(s.src_started_at AS Nullable(DateTime64(3,'UTC'))) AS `service_started_at`,
    CAST(s.src_ended_at AS Nullable(DateTime64(3,'UTC'))) AS `service_ended_at`,
    CAST(toDate(s.src_started_at,'Europe/Paris') AS Nullable(Date)) AS `service_start_date`,
    CAST(toTimeZone(toDateTime64(toDate(s.src_ended_at,'Europe/Paris')+1,3,'Europe/Paris'),'UTC') AS Nullable(DateTime64(3,'UTC'))) AS `service_end_exclusive_at`,
    CAST(s.src_state_id AS Nullable(Int64)) AS `line_state_id`,
    CAST(p.src_type_id AS Nullable(Int64)) AS `project_type_id`,
    CAST(p.src_started_at AS Nullable(DateTime64(3,'UTC'))) AS `project_started_at`,
    CAST(p.src_ended_at AS Nullable(DateTime64(3,'UTC'))) AS `project_ended_at`,
    CAST(if(isValidJSON(s.src_attributes) and JSONHas(s.src_attributes,'subscriptionQuantityCharged'),toDecimal128OrNull(JSONExtractRaw(s.src_attributes,'subscriptionQuantityCharged'),4),NULL) AS Nullable(Decimal(38,4))) AS `quantity`,
    CAST(if(isValidJSON(s.src_attributes) and JSONHas(s.src_attributes,'subscriptionPriceExcludingTax'),toDecimal128OrNull(JSONExtractRaw(s.src_attributes,'subscriptionPriceExcludingTax'),4),NULL) AS Nullable(Decimal(38,4))) AS `unit_monthly_price`,
    CAST(toDecimal128OrNull(toString(s.src_average_daily_price_excluding_tax),4) AS Nullable(Decimal(38,4))) AS `line_monthly_amount`,
    CAST(if(toDecimal128(quantity*unit_monthly_price,4)=quantity*unit_monthly_price,toDecimal128(quantity*unit_monthly_price,4),NULL) AS Nullable(Decimal(38,4))) AS `recomputed_quantity_price_amount`,
    CAST('EUR' AS Nullable(String)) AS `currency_code`,
    CAST(multiIf(line_monthly_amount is null,'missing_amount',line_monthly_amount<0,'invalid_amount','ready') AS String) AS `monetary_status`,
    CAST(NULL AS Nullable(String)) AS `continuity_key`,
    CAST('line_state_1_and_service_dates' AS String) AS `activity_rule_status`,
    CAST(s.source_version_key AS String) AS `source_delivery_version_key`,
    CAST(p.source_version_key AS Nullable(String)) AS `source_project_version_key`,
    CAST(li.first_at AS Nullable(DateTime64(3,'UTC'))) AS `coverage_start_at`,
    CAST({{ utc_var('case_as_of_boundary_at') }} AS Nullable(DateTime64(3,'UTC'))) AS `coverage_end_at`,
    CAST(not s.src_is_deleted and not ifNull(p.src_is_deleted,true) and co.company_key is not null AS Nullable(Bool)) AS `is_history_complete`,
    CAST(if(is_history_complete and monetary_status='ready','ready','partial') AS String) AS `calculation_status`,
    CAST(multiIf(co.company_key is null,'missing_company_link',s.src_is_deleted or ifNull(p.src_is_deleted,true),'incomplete_history',monetary_status!='ready','missing_amount',NULL) AS Nullable(String)) AS `status_reason`
from s left join projects p on s.src_tenant_id=p.src_tenant_id and s.src_project_id=p.src_id and s.boundary>=p.src_published_at and (p.next_at is null or s.boundary<p.next_at) left join {{ ref('dim_company') }} co on co.model_run_id={{ ch_literal(var('model_run_id','parse_only')) }} and p.src_tenant_id=co.tenant_id and p.src_company_id=co.company_id and s.boundary>=co.valid_from_at and (co.valid_to_at is null or s.boundary<co.valid_to_at) inner join line_identity li on s.src_tenant_id=li.src_tenant_id and s.src_id=li.src_id),
